mkdir -p /tmp/gwprobe && cat > /tmp/gwprobe/probe.js <<'EOF'
const WebSocket = require(process.argv[2] + '/node_modules/ws');
for (const v of [6, 10]) {
  const ws = new WebSocket(`wss://gateway.discord.gg/?v=${v}&encoding=json`);
  ws.on('message', m => { console.log(`v${v} msg op=`, JSON.parse(m).op); ws.close(); });
  ws.on('close', (c, r) => console.log(`v${v} close`, c, String(r)));
  ws.on('error', e => console.log(`v${v} error`, e.message));
}
EOF
cd /tmp && timeout 15 node /tmp/gwprobe/probe.js /work/repo; timeout 8 curl -sS https://discord.com/api/v6/gateway; echo
